-- 01_catalogos_y_base.sql: Tablas base y catálogos de valores (no dependen de nada)

CREATE TABLE "campanas" (
  "campana" TEXT NOT NULL,
  "anio_inicio" SMALLINT NOT NULL,
  "anio_fin" SMALLINT NOT NULL,
  PRIMARY KEY ("campana")
);

CREATE TABLE "participantes" (
  "participante_id" TEXT NOT NULL,
  "genero" TEXT,
  PRIMARY KEY ("participante_id")
);

CREATE TABLE "provincias" (
  "provincia_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" TEXT UNIQUE NOT NULL
);

CREATE TABLE "variedades" (
  "variedad_id" TEXT NOT NULL,
  "nombre_variedad" TEXT,
  PRIMARY KEY ("variedad_id")
);

CREATE TABLE "cat_sustrato" (
  "sustrato_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_sustrato_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("sustrato_id")
);

CREATE TABLE "cat_cultivo_asociado" (
  "cultivo_asociado_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_cultivo_asociado_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("cultivo_asociado_id")
);

CREATE TABLE "cat_fertilizacion" (
  "fertilizacion_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_fertilizacion_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("fertilizacion_id")
);

CREATE TABLE "cat_control_plagas" (
  "control_plagas_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_control_plagas_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("control_plagas_id")
);

CREATE TABLE "cat_causa_desuniformidad" (
  "causa_desuniformidad_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_causa_desuniformidad_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("causa_desuniformidad_id")
);

CREATE TABLE "cat_sanidad_observada" (
  "sanidad_observada_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_sanidad_observada_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("sanidad_observada_id")
);

CREATE TABLE "cat_causa_muerte_plantas" (
  "causa_muerte_plantas_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_causa_muerte_plantas_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("causa_muerte_plantas_id")
);

CREATE TABLE "cat_control_malezas" (
  "control_malezas_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_control_malezas_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("control_malezas_id")
);

CREATE TABLE "cat_cobertura_suelo" (
  "cobertura_suelo_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_cobertura_suelo_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("cobertura_suelo_id")
);

CREATE TABLE "etapas" (
  "etapa_id" INTEGER NOT NULL,
  "nombre" TEXT NOT NULL,
  PRIMARY KEY ("etapa_id")
);

CREATE UNIQUE INDEX "uq_cat_sustrato_valor" ON "cat_sustrato" ("valor");

CREATE UNIQUE INDEX "uq_cat_cultivo_asociado_valor" ON "cat_cultivo_asociado" ("valor");

CREATE UNIQUE INDEX "uq_cat_fertilizacion_valor" ON "cat_fertilizacion" ("valor");

CREATE UNIQUE INDEX "uq_cat_control_plagas_valor" ON "cat_control_plagas" ("valor");

CREATE UNIQUE INDEX "uq_cat_causa_desuniformidad_valor" ON "cat_causa_desuniformidad" ("valor");

CREATE UNIQUE INDEX "uq_cat_sanidad_observada_valor" ON "cat_sanidad_observada" ("valor");

CREATE UNIQUE INDEX "uq_cat_causa_muerte_plantas_valor" ON "cat_causa_muerte_plantas" ("valor");

CREATE UNIQUE INDEX "uq_cat_control_malezas_valor" ON "cat_control_malezas" ("valor");

CREATE UNIQUE INDEX "uq_cat_cobertura_suelo_valor" ON "cat_cobertura_suelo" ("valor");
